  def sillage_icon(name, size: 18, class_name: "sillage-icon", stroke_width: 2)
    path = SILLAGE_ICON_PATHS[name.to_s]
    return "".html_safe unless path

    content_tag(
      :svg,
      raw(path),
      viewBox: "0 0 24 24",
      width: size,
      height: size,
      fill: "none",
      stroke: "currentColor",
      "stroke-width": stroke_width,
      "stroke-linecap": "round",
      "stroke-linejoin": "round",
      class: class_name,
      aria: { hidden: true },
      focusable: "false"
    )
  end

  def sillage_current_room
    return "signal" if controller_path == "signal" || controller_path == "signal_sessions"
    return "hangar" if controller_path.start_with?("hangar/")
    return "forge" if controller_path.start_with?("forge/")
    return "core" if controller_path.start_with?("core/")

    "flight"
  end

  def sillage_shell_title
    content_for(:title).presence || t("app.name")
  end

  def sillage_current_tab_label
    if sillage_current_room == "flight"
      sillage_flight_tabs.find { |tab| tab[:id] == sillage_current_flight_tab }&.fetch(:label) || sillage_shell_title
    elsif controller_path.start_with?("core/")
      "Users"
    elsif controller_path.start_with?("hangar/")
      controller_name.titleize
    elsif controller_path.start_with?("forge/")
      controller_name == "fdrs" ? "Embedded controllers" : controller_name.titleize
    else
      "Overview"
    end
  end

  def sillage_breadcrumb_items
    [
      { label: t("app.name"), href: root_path },
      { label: sillage_shell_crumb, current: true }
    ]
  end

  def sillage_shell_crumb
    return "Hangar" if sillage_current_room == "hangar"
    return "Signal" if sillage_current_room == "signal"
    return "Forge" if sillage_current_room == "forge"
    return sillage_current_tab_label if sillage_current_room == "core"

    case sillage_current_flight_tab
    when "prep" then "Pre-flight"
    when "replay" then "Replay & analysis"
    when "hud" then "Pilot display"
    else "Operations"
    end
  end

  def sillage_room_items
    [
      { id: "flight", label: "Flights", icon: "plane", href: flights_path, enabled: true },
      { id: "hangar", label: "Hangar", icon: "wrench", href: hangar_path, enabled: true },
      { id: "forge", label: "Forge", icon: "code", href: forge_path, enabled: true },
      { id: "signal", label: "Signal", icon: "signal", href: signal_path, enabled: true, separated: true }
    ]
  end

  def sillage_current_flight_tab
    return "hud" if controller_name == "dashboard" && action_name == "hud"
    return "prep" if controller_name == "flight_imports" && %w[new create].include?(action_name)
    return "replay" if controller_name == "flights" && action_name == "show"

    "logbook"
  end

  def sillage_flight_tabs
    [
      { id: "logbook", label: "Flights", href: flights_path, enabled: true },
      { id: "prep", label: "Flight prep", href: new_flight_path, enabled: true },
      { id: "hud", label: "HUD", href: flight_hud_path, enabled: true }
    ]
  end

  def sillage_show_flight_tabs?
    sillage_current_room == "flight" && sillage_current_flight_tab != "replay"
  end

  def sillage_content_shell_class
    classes = [ "app-shell" ]
    classes << "is-full-bleed" if sillage_current_flight_tab == "replay" || sillage_current_room == "signal"
    classes.join(" ")
  end

  def sillage_user_initials(user)
    return "--" unless user

    parts = user.email_address.to_s.split("@").first.to_s.split(/[._-]/).reject(&:blank?)
    initials = parts.first(2).map { |part| part[0] }.join
    initials.presence&.upcase || user.email_address.to_s.first(2).upcase
  end
end
